+  const localDef = (src, k) => new RegExp(`(^|\\n)\\s*(export\\s+)?(const\\s+${k}\\s*=|function\\s+${k}\\s*\\()`).test(src);
+  for (const k of ['mergeIv', 'ivIntersect', 'ivSpan', 'concurrentWith']) {
