+/*
+ * tools/fold-intervals.js — Tepna
+ * Copyright 2026 Michal Planicka
+ * SPDX-License-Identifier: Apache-2.0
+ * Licensed under the Apache License, Version 2.0. See LICENSE and NOTICE at the
+ * project root, or http://www.apache.org/licenses/LICENSE-2.0
+ *
+ * THE FOLD'S SESSION-MERGE RULE — which fragments make up a night — as one importable module.
+ * Residue `2026-09-29-fold-session-merge-rule-is-module-local-to-trio-batch`.
+ *
+ * WHY THIS FILE EXISTS. `trio-batch.mjs` runs its night loop at import, so a const inside it cannot be
+ * imported: `tools/cvhr-fold-rescore.mjs` needed exactly this rule and had to re-derive it, then prove
+ * the copy against 23 committed rows. That is the defect of residue
+ * `2026-09-22-cvhr-overlap-four-of-six-were-the-sweeps-selection`, one tool over. The rule lives here,
+ * pure (no I/O, no logging), the same reason `drift-report.js` and `trio-anchor.mjs` were extracted.
+ *
+ * A window is `[startMs, endMs]` on the floating wall-clock axis (Clock Contract §1). A night is the
+ * MEASURE of its merged sessions, never the distance between the first start and the last end.
+ */
+(function (root) {
+  'use strict';
+
+  /* Sort by start, merge touching or overlapping windows. A null window (an unreadable file) is
+     skipped: it adds no time, and it is never a zero-length session. */
+  function mergeIv(windows) {
+    const ok = windows.filter(Boolean).slice();
+    ok.sort((a, b) => a[0] - b[0]);
+    const out = [];
+    for (const w of ok) {
+      const last = out[out.length - 1];
+      if (last && w[0] <= last[1]) last[1] = Math.max(last[1], w[1]);
+      else out.push([w[0], w[1]]);
+    }
+    return out;
+  }
+
+  /* Intersection of two MERGED interval sets. */
+  function ivIntersect(A, B) {
+    const out = [];
+    let i = 0;
+    let j = 0;
+    while (i < A.length && j < B.length) {
+      const s = Math.max(A[i][0], B[j][0]);
+      const e = Math.min(A[i][1], B[j][1]);
+      if (e > s) out.push([s, e]);
+      if (A[i][1] < B[j][1]) i++;
+      else j++;
+    }
+    return out;
+  }
+
+  /* Total measure of a merged interval set, in the unit of its windows. */
+  function ivSpan(A) {
+    return A.reduce((t, w) => t + (w[1] - w[0]), 0);
+  }
+
+  /* EVERY record of a stream that touches the night's merged anchor — not the single best one. A record
+     with zero overlap is dropped (a daytime capture is not this night's sleep). `winOf(record)` gives the
+     record's window. `minOverlapMs` is the caller's floor and is REQUIRED: a missing floor is a caller
+     bug, not a silent zero.
+     Returns null when there is nothing to judge (no records, or no anchor). Otherwise returns
+     `{ kept, overlapMs, dropped, enough }`: `kept` sorted by start, `overlapMs` the merged overlap of
+     `kept` with the anchor, and `enough` false when that overlap is below the floor. */
+  function concurrentSet(items, anchorIv, winOf, minOverlapMs) {
+    if (!Number.isFinite(minOverlapMs)) throw new TypeError('concurrentSet: minOverlapMs must be a finite number of ms');
+    if (!items || !items.length || !anchorIv || !anchorIv.length) return null;
+    const kept = items.filter((r) => ivSpan(ivIntersect(mergeIv([winOf(r)]), anchorIv)) > 0);
+    const overlapMs = ivSpan(ivIntersect(mergeIv(kept.map(winOf)), anchorIv));
+    kept.sort((a, b) => winOf(a)[0] - winOf(b)[0]);
+    return { kept: kept, overlapMs: overlapMs, dropped: items.length - kept.length, enough: !(overlapMs < minOverlapMs) };
+  }
+
+  root.FoldIntervals = {
+    mergeIv: mergeIv,
+    ivIntersect: ivIntersect,
+    ivSpan: ivSpan,
+    concurrentSet: concurrentSet
+  };
+  if (typeof module !== 'undefined' && module.exports) module.exports = root.FoldIntervals;
+})(typeof globalThis !== 'undefined' ? globalThis : typeof self !== 'undefined' ? self : this);
