+     halves moves one code unit OUTWARD, so the chunk keeps the whole character. The loop, the stride
+     and the break are unchanged, so the chunk COUNT never moves and a cut that was whole stays
+     byte-identical — the cache's positional pairing of vector i with chunk i holds. */
+  const mid = (k) => k > 0 && k < t.length && (t.charCodeAt(k) & 0xfc00) === 0xdc00 && (t.charCodeAt(k - 1) & 0xfc00) === 0xd800;
